28	/**
29	 * Class representing the metadata for a functional index in Hudi.
30	 */
31	@JsonIgnoreProperties(ignoreUnknown = true)
32	public class HoodieFunctionalIndexDefinition implements Serializable {
33	
34	  // Name of the index
35	  private String indexName;
36	
37	  private String indexType;
38	
39	  // Expression used for the index, e.g., MONTH(ts)
40	  private String indexFunction;
41	
42	  // Data fields the expression is derived from
43	  private List<String> sourceFields;
44	
45	  // Any other configuration or properties specific to the index
46	  private Map<String, String> indexOptions;
47	
48	  public HoodieFunctionalIndexDefinition() {
49	  }
50	
51	  public HoodieFunctionalIndexDefinition(String indexName, String indexType, String indexFunction, List<String> sourceFields,
52	                                         Map<String, String> indexOptions) {
53	    this.indexName = indexName;
54	    this.indexType = indexType;
55	    this.indexFunction = indexFunction;
56	    this.sourceFields = sourceFields;
57	    this.indexOptions = indexOptions;
58	  }
59	
60	  public String getIndexFunction() {
61	    return indexFunction;
62	  }
63	
64	  public List<String> getSourceFields() {
65	    return sourceFields;
66	  }
67	
68	  public Map<String, String> getIndexOptions() {
69	    return indexOptions;
70	  }
71	
72	  public String getIndexName() {
73	    return indexName;
74	  }
75	
76	  public String getIndexType() {
77	    return indexType;
78	  }
79	
80	  @Override
81	  public String toString() {
82	    return "HoodieFunctionalIndexDefinition{"
83	        + "indexName='" + indexName + '\''
84	        + ", indexType='" + indexType + '\''
85	        + ", indexFunction='" + indexFunction + '\''
86	        + ", sourceFields=" + sourceFields
87	        + ", indexOptions=" + indexOptions
88	        + '}';
89	  }
90	}
