39	
40	  private static final Logger LOG = LoggerFactory.getLogger(HoodieFunctionalIndexMetadata.class);
41	
42	  // Map to hold the index definitions keyed by their names.
43	  private Map<String, HoodieFunctionalIndexDefinition> indexDefinitions;
44	
45	  public HoodieFunctionalIndexMetadata() {
46	    this.indexDefinitions = new HashMap<>();
47	  }
48	
