50	    this.indexDefinitions = indexDefinitions;
51	  }
52	
53	  public Map<String, HoodieFunctionalIndexDefinition> getIndexDefinitions() {
54	    return indexDefinitions;
55	  }
56	
57	  public void setIndexDefinitions(Map<String, HoodieFunctionalIndexDefinition> indexDefinitions) {
58	    this.indexDefinitions = indexDefinitions;
59	  }
60	
61	  /**
62	   * Serialize this object to JSON string.
63	   *
64	   * @return Serialized JSON string.
65	   * @throws JsonProcessingException If any serialization errors occur.
66	   */
67	  public String toJson() throws JsonProcessingException {
68	    if (indexDefinitions.containsKey(null)) {
69	      LOG.info("null index name for the index definition " + indexDefinitions.get(null));
70	      indexDefinitions.remove(null);
71	    }
72	    return JsonUtils.getObjectMapper().writerWithDefaultPrettyPrinter().writeValueAsString(this);
73	  }
74	
75	  /**
76	   * Deserialize from JSON string to create an instance of this class.
77	   *
78	   * @param json Input JSON string.
79	   * @return Deserialized instance of HoodieFunctionalIndexMetadata.
80	   * @throws IOException If any deserialization errors occur.
81	   */
82	  public static HoodieFunctionalIndexMetadata fromJson(String json) throws IOException {
83	    if (json == null || json.isEmpty()) {
84	      return new HoodieFunctionalIndexMetadata();
85	    }
86	    return JsonUtils.getObjectMapper().readValue(json, HoodieFunctionalIndexMetadata.class);
87	  }
88	
89	  @Override
90	  public String toString() {
91	    return "HoodieFunctionalIndexMetadata{"
92	        + "indexDefinitions=" + indexDefinitions
93	        + '}';
