41	/**
42	 * Partition types for metadata table.
43	 */
44	public enum MetadataPartitionType {
45	  FILES(HoodieTableMetadataUtil.PARTITION_NAME_FILES, "files-") {
46	    @Override
47	    public boolean isMetadataPartitionEnabled(TypedProperties writeConfig) {
48	      return getBooleanWithAltKeys(writeConfig, ENABLE);
49	    }
50	  },
51	  COLUMN_STATS(HoodieTableMetadataUtil.PARTITION_NAME_COLUMN_STATS, "col-stats-") {
52	    @Override
53	    public boolean isMetadataPartitionEnabled(TypedProperties writeConfig) {
54	      return getBooleanWithAltKeys(writeConfig, ENABLE_METADATA_INDEX_COLUMN_STATS);
55	    }
56	  },
57	  BLOOM_FILTERS(HoodieTableMetadataUtil.PARTITION_NAME_BLOOM_FILTERS, "bloom-filters-") {
58	    @Override
59	    public boolean isMetadataPartitionEnabled(TypedProperties writeConfig) {
60	      return getBooleanWithAltKeys(writeConfig, ENABLE_METADATA_INDEX_BLOOM_FILTER);
61	    }
62	  },
63	  RECORD_INDEX(HoodieTableMetadataUtil.PARTITION_NAME_RECORD_INDEX, "record-index-") {
64	    @Override
65	    public boolean isMetadataPartitionEnabled(TypedProperties writeConfig) {
66	      return getBooleanWithAltKeys(writeConfig, RECORD_INDEX_ENABLE_PROP);
67	    }
68	  },
69	  FUNCTIONAL_INDEX(HoodieTableMetadataUtil.PARTITION_NAME_FUNCTIONAL_INDEX_PREFIX, "func-index-") {
70	    @Override
71	    public boolean isMetadataPartitionEnabled(TypedProperties writeConfig) {
72	      // Functional index is created via sql and not via write path.
73	      // HUDI-7662 tracks adding a separate config to enable/disable functional index.
74	      return false;
75	    }
76	
77	    @Override
78	    public boolean isMetadataPartitionAvailable(HoodieTableMetaClient metaClient) {
79	      return metaClient.getFunctionalIndexMetadata().isPresent();
80	    }
81	  },
82	  PARTITION_STATS(HoodieTableMetadataUtil.PARTITION_NAME_PARTITION_STATS, "partition-stats-") {
83	    @Override
84	    public boolean isMetadataPartitionEnabled(TypedProperties writeConfig) {
85	      return getBooleanWithAltKeys(writeConfig, ENABLE_METADATA_INDEX_PARTITION_STATS) && nonEmpty(getStringWithAltKeys(writeConfig, COLUMN_STATS_INDEX_FOR_COLUMNS, EMPTY_STRING));
86	    }
87	  };
88	
89	  // Partition path in metadata table.
90	  private final String partitionPath;
91	  // FileId prefix used for all file groups in this partition.
92	  private final String fileIdPrefix;
93	
94	  /**
95	   * Check if the metadata partition is enabled based on the metadata config.
96	   */
97	  public abstract boolean isMetadataPartitionEnabled(TypedProperties writeConfig);
98	
99	  /**
100	   * Check if the metadata partition is available based on the table config.
101	   */
102	  public boolean isMetadataPartitionAvailable(HoodieTableMetaClient metaClient) {
103	    return metaClient.getTableConfig().isMetadataPartitionAvailable(this);
104	  }
105	
106	  MetadataPartitionType(final String partitionPath, final String fileIdPrefix) {
107	    this.partitionPath = partitionPath;
108	    this.fileIdPrefix = fileIdPrefix;
109	  }
110	
111	  public String getPartitionPath() {
112	    return partitionPath;
113	  }
114	
115	  public String getFileIdPrefix() {
116	    return fileIdPrefix;
117	  }
118	
119	  /**
120	   * Returns the list of metadata table partitions which require WriteStatus to track written records.
121	   * <p>
122	   * These partitions need the list of written records so that they can update their metadata.
123	   */
124	  public static List<MetadataPartitionType> getMetadataPartitionsNeedingWriteStatusTracking() {
125	    return Collections.singletonList(MetadataPartitionType.RECORD_INDEX);
126	  }
127	
128	  /**
129	   * Returns the set of all metadata partition names.
130	   */
131	  public static Set<String> getAllPartitionPaths() {
132	    return Arrays.stream(values())
133	        .map(MetadataPartitionType::getPartitionPath)
134	        .collect(Collectors.toSet());
135	  }
136	
137	  /**
138	   * Returns the list of metadata partition types enabled based on the metadata config and table config.
139	   */
140	  public static List<MetadataPartitionType> getEnabledPartitions(TypedProperties writeConfig, HoodieTableMetaClient metaClient) {
141	    return Arrays.stream(values())
142	        .filter(partitionType -> partitionType.isMetadataPartitionEnabled(writeConfig) || partitionType.isMetadataPartitionAvailable(metaClient))
143	        .collect(Collectors.toList());
144	  }
145	
146	  @Override
147	  public String toString() {
148	    return "Metadata partition {"
149	        + "name: " + getPartitionPath()
150	        + ", prefix: " + getFileIdPrefix()
151	        + "}";
152	  }
153	}
